//! Dioxus: rendered in the browser (client-side rendering into `<div id="main">`).
//!
//! Dioxus' web hydration reads data that its fullstack server injects into the page
//! (`window.initial_dioxus_hydration_data`, written by an inline script), so it needs the
//! dioxus fullstack stack; without it, the idiomatic dioxus web app renders on the client.

use bench_common::COUNTER_START;
use dioxus::prelude::*;

/// Library name, which names the files generated by wasm-bindgen.
pub const LIB: &str = "counter_dioxus";

/// A button that increments the number next to it.
#[component]
pub fn App() -> Element {
    let mut count = use_signal(|| COUNTER_START);
    // Effects run once the first render is in the DOM.
    use_effect(|| bench_common::mark("data-ready"));
    rsx! {
        button { id: "inc", onclick: move |_| count += 1, "+1" }
        span { id: "count", "{count}" }
    }
}

/// The server HTML: an empty root, filled by the browser bundle.
#[cfg(not(target_arch = "wasm32"))]
pub fn page() -> String {
    bench_common::counter_page(LIB, r#"<div id="main"></div>"#)
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen::prelude::wasm_bindgen(start)]
pub fn start() {
    bench_common::mark("data-start");
    // Asynchronous: renders on the next tick, then runs the effect above.
    dioxus::launch(App);
}
